# ======================================================================
class WavefrontLockedObserver:
    """The observer locked to the advancing e4-wavefront reads e4 as TIME.
    Gamma matrices are built INSIDE Cl(4,0):  gamma^0 = e4,  gamma^j = e4 e_j.
    The Lorentzian signature is then COMPUTED, not assumed."""

    def gammas(self):
        """[DERIVED] Sec 12.1: the four gamma^mu as elements of Cl(4,0)."""
        return [e(4), e(4) * e(1), e(4) * e(2), e(4) * e(3)]

    def dirac_metric(self):
        """[DERIVED] Sec 12.2: eta^{mu nu} = (1/2){gamma^mu, gamma^nu}, COMPUTED.
        Returns the 4x4 scalar matrix — should be diag(+1,-1,-1,-1)."""
        g = self.gammas()
        eta = [[0.0] * 4 for _ in range(4)]
        for mu in range(4):
            for nu in range(4):
                anti = g[mu] * g[nu] + g[nu] * g[mu]      # {gamma^mu, gamma^nu}
                eta[mu][nu] = 0.5 * anti.coeff(())         # scalar part
        return eta

    def signature(self):
        """The diagonal of the computed metric: the signature read FROM INSIDE."""
        return [self.dirac_metric()[i][i] for i in range(4)]

    def spatial_axes_are_Q_bivectors(self):
        """[DERIVED] Sec 12.5: each gamma^j = e4 e_j is a Q-orbit bivector — observer-space
        and the quark orbit are ONE structure."""
        return all(is_Q_bivector(self.gammas()[j]) for j in (1, 2, 3))

    def outside_vs_inside(self):
        return {
            "outside (substrate)": "Euclidean Cl(4,0): all e_i^2 = +1",
            "inside (wavefront-locked)": "Lorentzian Cl(1,3): gamma^0^2=+1 (time), gamma^j^2=-1 (space)",
            "same algebra": "both ≅ M_2(H); the flip is RELABELING via gamma^mu, not indefinite substrate",
        }


