    out = {}
    # su(3) writable: extraction exact
    Psi, al, be = _rand_colour_state(3)
    out["su3_writable (extraction round-trip exact)"] = all(
        abs(blade_amplitude_extract(Psi, a)[0] - al[a]) < 1e-12 and
        abs(blade_amplitude_extract(Psi, a)[1] - be[a]) < 1e-12 for a in range(3))
