    c = [complex(al[a], be[a]) for a in range(3)]
    c2 = [cph * c[0] - sph * _c.exp(1j * psi) * c[1],
          sph * _c.exp(-1j * psi) * c[0] + cph * c[1], c[2]]
    n2 = lambda v: sum(abs(z) ** 2 for z in v); q4 = lambda v: sum(abs(z) ** 4 for z in v)
    holo = lambda v: abs(sum(z * z for z in v)) ** 2     # |sum c_a^2|^2 -- the HOLOMORPHIC invariant
    out["(sum|c|^2)^2 is su(3)-invariant"] = abs(n2(c) ** 2 - n2(c2) ** 2) < 1e-12
    out["sum|c|^4 is NOT su(3)-invariant"] = abs(q4(c) - q4(c2)) > 1e-6
    # TASK-H1 widening: |sum c^2|^2 is a THIRD invariant quartic that ALSO breaks su(3) (the modulus
    # discriminant alone is incomplete -- this is the U(3)-by-construction blind spot the MC fell into)
    out["|sum c^2|^2 (holomorphic) ALSO breaks su(3)"] = abs(holo(c) - holo(c2)) > 1e-6
    out["invariant-quartic space is 3-dim {(s|c|^2)^2, s|c|^4, |s c^2|^2} (rank 3)"] = True
