    # forced U(3) at the QUADRATIC level does NOT extend to forbid it at the QUARTIC level. U(3) at quartic
    # level survives iff the dynamics couples ONLY to the charge-0 modulus, NOT to the charge-2 bilinear.
    import cmath as _cm
    _th = 0.7; _cp = [_cm.exp(1j * _th) * z for z in c]
