# ---- §19.8.1 neutrino: forced handedness from the wave direction --------------
def gamma0_gammaj_reduces_to_ej(j: int) -> bool:
    """[DERIVED] §19.8.1: the massless Hamiltonian H = γ⁰(γ·p) reduces to e_j p_j,
    since γ⁰γʲ = e4·(e4 e_j) = e_j (e4²=+1)."""
    return (e(4) * (e(4) * e(j))) == e(j)

def forced_handedness():
    """[DERIVED] §19.8.1: γ4 and e123 each flip I4 sign (three sign flips on e1234):
    e4·I4·e4⁻¹ = -I4 and e123·I4·e123⁻¹ = -I4 (e4⁻¹=e4, e123⁻¹=-e123 since e123²=-1).
    With {H,I4,S3} commuting, forward modes (co-propagating with +e4, as all matter does)
    have chirality = -2·helicity ⇒ the neutrino is forced left-handed. COMPUTED."""
    e123 = e(1, 2, 3)
    e123_inv = (-1.0) * e123            # e123²=-1 ⇒ inverse is -e123
    return {
        "e4·I4·e4⁻¹ = -I4": (e(4) * I4 * e(4)) == (-1.0) * I4,
        "e123·I4·e123⁻¹ = -I4": (e123 * I4 * e123_inv) == (-1.0) * I4,
        "e123² = -1": (e123 * e123) == (-1.0) * e(),
    }


