    assert lnt["L(Q-orbit defect)"] == 0, "L = 0 on Q-orbit defect (orthogonal to baryon channel)"
    # Engine-witness the B=0 no-protection (mesons decay → no stable B=0 massive singlet)
    mes = meson_topological_status()
    assert mes["topologically_protected"] is False, "B=0 meson sector must NOT be protected"
    # The enumeration table
