    l = {1: [[0, 1, 0], [1, 0, 0], [0, 0, 0]], 2: [[0, -1j, 0], [1j, 0, 0], [0, 0, 0]], 3: [[1, 0, 0], [0, -1, 0], [0, 0, 0]],
         4: [[0, 0, 1], [0, 0, 0], [1, 0, 0]], 5: [[0, 0, -1j], [0, 0, 0], [1j, 0, 0]], 6: [[0, 0, 0], [0, 0, 1], [0, 1, 0]],
         7: [[0, 0, 0], [0, 0, -1j], [0, 1j, 0]]}
    l = {k: np.array(v, complex) for k, v in l.items()}
    l[8] = np.array([[1, 0, 0], [0, 1, 0], [0, 0, -2]], complex) / np.sqrt(3)
    so3, coset = [2, 5, 7], [1, 3, 4, 6, 8]                       # so(3) subalgebra (imag-antisym) vs SU(3)/SO(3) coset (real-sym)
    comm = lambda a, b: l[a] @ l[b] - l[b] @ l[a]
    coef = lambda M, k: np.trace(l[k].conj().T @ M) / np.trace(l[k].conj().T @ l[k])
