    g35 = max(leak(comm(a, b), so3) for a in so3 for b in coset)                            # [3,5]⊂coset: no so(3) leak
    g55 = max(leak(comm(a, b), coset) for i, a in enumerate(coset) for b in coset[i + 1:])  # [5,5]⊂so(3): no coset leak (symmetric space)
    assert g33 < 1e-9 and g35 < 1e-9 and g55 < 1e-9              # the Z2 symmetric-space grading, exact
    span = np.array([[coef(comm(a, b), k) for k in so3] for i, a in enumerate(coset) for b in coset[i + 1:]])
