    I4 = e(1, 2, 3, 4)
    E5 = e(1, 2, 3, 4, 5)
    KEYS = [()] + [tuple(c) for k in range(1, 6)
                   for c in _it.combinations(range(1, 6), k)]

    def _coords(x):
        return np.array([x.coeff(k) for k in KEYS])

    def _mvnorm(x):
        return sum(abs(c) for _, c in x.terms)

    def _rotor(u, th):
        return math.cos(th / 2.0) * ONE + math.sin(th / 2.0) * u

    def _parity(x):
        out = {}
        for k, c in x.terms:
            nsp = sum(1 for i in k if i in (1, 2, 3))
            out[k] = out.get(k, 0.0) + c * ((-1) ** nsp)
        return MV.from_dict(out)

    EVEN8 = [ONE, e(1, 2), e(1, 3), e(1, 4), e(2, 3), e(2, 4), e(3, 4), I4]
    Q_ORBIT = {"e14": e(1, 4), "e24": e(2, 4), "e34": e(3, 4)}
    L_ORBIT = [e(1, 2), e(1, 3), e(2, 3)]
    omega, th_gen = 0.937, 1.234

