    def _cnorm(M):
        return math.sqrt(sum(c * c for _, c in M.terms))

    g = gammas()

    # ---- grade-shift fact: gamma^0 gamma^j = e_j (observer bivector = substrate vector)
    grade_shift = all(_cnorm(g[0] * g[j] - e(j)) < 1e-14 for j in (1, 2, 3))

    # ---- hyperbolic boost rotor + rapidity addition
    def _B(j, z):
        return math.cosh(z / 2.0) * ONE + math.sinh(z / 2.0) * e(j)

    z1, z2, z = 0.83, 1.47, 0.83
    K_sq = all(_cnorm(boost(j) * boost(j) - 0.25 * ONE) < 1e-14 for j in (1, 2, 3))
    rapidity_add = all(
        _cnorm(_B(j, z1) * _B(j, z2) - _B(j, z1 + z2)) < 1e-12 for j in (1, 2, 3))

    # ---- vector action on the gamma frame (axis boost along e_1)
    B, Binv = _B(1, z), _B(1, -z)
