    g2p = B * g[2] * Binv
    vec_action = (
        _cnorm(g0p - (math.cosh(z) * g[0] + (-1.0) * math.sinh(z) * g[1])) < 1e-12
        and _cnorm(g1p - (math.cosh(z) * g[1] + (-1.0) * math.sinh(z) * g[0])) < 1e-12
        and _cnorm(g2p - g[2]) < 1e-12)

    # ---- mass shell: rest label m gamma^0, m = omega/c_meta generic
    omega, c_meta = 0.937, 1.31
    m = omega / c_meta
    kslash = m * g[0]
    kp = B * kslash * Binv
    shell_algebraic = _cnorm(kp * kp - (m * m) * ONE) < 1e-12

    def _components(kx):
        E = kx.coeff((4,))
        psq = 0.0
        for jj in (1, 2, 3):
            blade = (jj, 4)
            sj = g[jj].coeff(blade)
            psq += (kx.coeff(blade) / sj) ** 2
        return E, psq

