    n = (0.481, -0.637, 0.602)
    s = math.sqrt(sum(x * x for x in n))
    n = tuple(x / s for x in n)
    ne = n[0] * e(1) + n[1] * e(2) + n[2] * e(3)
    Bn = math.cosh(z / 2) * ONE + math.sinh(z / 2) * ne
    Bn_inv = math.cosh(z / 2) * ONE - math.sinh(z / 2) * ne
    kp2 = Bn * kslash * Bn_inv
    E2, psq2 = _components(kp2)
    R12 = math.cos(0.4135) * ONE + math.sin(0.4135) * e(1, 2)
    R12_inv = math.cos(0.4135) * ONE - math.sin(0.4135) * e(1, 2)
    kp3 = R12 * kp2 * R12_inv
    E3, psq3 = _components(kp3)
    shell_generic = (_cnorm(ne * ne - ONE) < 1e-12
                     and _cnorm(kp2 * kp2 - (m * m) * ONE) < 1e-12
                     and abs(E2 * E2 - psq2 - m * m) < 1e-12
                     and _cnorm(kp3 * kp3 - (m * m) * ONE) < 1e-12
                     and abs(E3 * E3 - psq3 - m * m) < 1e-12
                     and abs(E3 - E2) < 1e-12)

    # ---- caveat defusal side-by-side: e_{14} rotation circular, e_1 boost hyperbolic
    th = z
    circ = math.cos(th / 2) * ONE + math.sin(th / 2) * e(1, 4)
    circ_inv = math.cos(th / 2) * ONE - math.sin(th / 2) * e(1, 4)
