    s2 = 1.0 / math.sqrt(2.0)
    SDb = [s2 * (e(1, 2) - e(3, 4)), s2 * (e(1, 3) + e(2, 4)), s2 * (e(1, 4) - e(2, 3))]
    ASDb = [s2 * (e(1, 2) + e(3, 4)), s2 * (e(1, 3) - e(2, 4)), s2 * (e(1, 4) + e(2, 3))]

    def gr0(m): return m.grade(0).coeff(())
    def coeff_in(m, basis): return np.array([gr0(m * b.reverse()) for b in basis])
    def combo(cs, basis):
        out = MV.from_dict({})
        for ci, b in zip(cs, basis):
            out = out + float(ci) * b
        return out

    # ---- (1) the SIGNED identity ----
    max_signed = max_cross = 0.0
    for _ in range(40):
        cs = [rnd.uniform(-1, 1) for _ in G2]
        B = combo(cs, G2)
        cS, cA = coeff_in(B, SDb), coeff_in(B, ASDb)
        lhs = gr0(B * I4 * B)
        rhs = float(cA @ cA - cS @ cS)                    # |B_ASD|^2 - |B_SD|^2  (SIGNED)
        cross = 2.0 * gr0(combo(cs[:3], G2[:3]) * I4 * combo(cs[3:], G2[3:]))
        max_signed = max(max_signed, abs(lhs - rhs))
        max_cross = max(max_cross, abs(lhs - cross))
    assert max_signed < TOL, "<B I4 B>_0 = |B_ASD|^2 - |B_SD|^2 must hold SIGNED (%.2e)" % max_signed
    assert max_cross < TOL, "<B I4 B>_0 = 2<B_L I4 B_Q>_0 must hold SIGNED (%.2e)" % max_cross
    assert abs(gr0(SDb[0] * I4 * SDb[0]) + 1.0) < TOL, "sign convention: <SD I4 SD>_0 must be -1"
    # exact integer-coefficient witness (no random draw)
    ci = [3, -1, 4, 1, -5, 9]
    Bi = combo(ci, G2)
    lhs_i = gr0(Bi * I4 * Bi)
    rhs_i = float(coeff_in(Bi, ASDb) @ coeff_in(Bi, ASDb) - coeff_in(Bi, SDb) @ coeff_in(Bi, SDb))
    cross_i = 2.0 * gr0(combo(ci[:3], G2[:3]) * I4 * combo(ci[3:], G2[3:]))
    assert abs(lhs_i - 52.0) < TOL and abs(rhs_i - 52.0) < TOL and abs(cross_i - 52.0) < TOL, \
        (lhs_i, rhs_i, cross_i)

    # ---- (2) identical vanishing on grade-3 (bilinear => the blade basis suffices) ----
    for a in G3:
        for b in G3:
            assert abs(gr0(a * I4 * b)) < 1e-14, "<X I4 X>_0 must vanish identically on grade-3"
    i4x_grades = set()
    for b in G3:
        i4x_grades |= {len(k) for k, cx in (I4 * b).terms if abs(cx) > 1e-14}
    assert i4x_grades == {1}, "the grade-counting proof needs I4*X of grade 1; got %s" % i4x_grades
    # the coset partner is the EXTERNAL-phase blade, not Cl(4,0) grade-2
    ex = wave_E5() * e(1, 2, 4)
    exb = [b for b, cx in ex.terms if abs(cx) > 1e-12]
    assert exb == [(3, 5)] and all(5 in b for b in exb), "E*e124 must be the e35 external partner"

    # ---- symmetry actions, built FROM the engine's own commutator (no convention risk) ----
    def ad_matrix(gen, basis):
        cols = []
        for b in basis:
            c = 0.5 * (gen * b - b * gen)
            v = coeff_in(c, basis)
            rec = combo(v, basis)
            assert max([abs(x) for _, x in (c - rec).terms], default=0.0) < TOL, "action leaves span"
            cols.append(v)
        return np.array(cols).T

    BIV6 = list(G2)
    A2 = [ad_matrix(b, G2) for b in BIV6]          # full so(4) on grade-2
    A3 = [ad_matrix(b, G3) for b in BIV6]          # full so(4) on grade-3
    A2sp = [ad_matrix(b, G2) for b in SP]          # spatial so(3) on grade-2
    Acol = [ad_matrix(b, COL) for b in SP]         # spatial so(3) on the colour triple
    for b in SP:                                   # e123 is a spatial scalar
        c = 0.5 * (b * e(1, 2, 3) - e(1, 2, 3) * b)
        assert max([abs(x) for _, x in c.terms], default=0.0) < TOL
    assert all(abs(A[i, j]) < TOL for A in A2sp for i in range(3) for j in range(3, 6)) and \
           all(abs(A[i, j]) < TOL for A in A2sp for i in range(3, 6) for j in range(3)), \
           "spatial so(3) must preserve the L / Q blocks on grade-2"

    # octet reps from the SAME engine-built colour action
    so3_basis, sym0_basis = [], []
    for (i, j) in [(0, 1), (0, 2), (1, 2)]:
        M = np.zeros((3, 3)); M[i, j] = 1.0; M[j, i] = -1.0; so3_basis.append(M)
        S = np.zeros((3, 3)); S[i, j] = 1.0; S[j, i] = 1.0; sym0_basis.append(S)
    Dg1 = np.diag([1.0, -1.0, 0.0]); Dg2 = np.diag([1.0, 1.0, -2.0]) / math.sqrt(3.0)
    sym0_basis += [Dg1 / np.linalg.norm(Dg1), Dg2 / np.linalg.norm(Dg2)]

    def rep_on_matspace(A, basis):
        Bn = [M / np.linalg.norm(M) for M in basis]
        cols = []
        for M in Bn:
            C = A @ M - M @ A
            v = np.array([np.sum(C * N) for N in Bn])
            assert np.max(np.abs(C - sum(vi * N for vi, N in zip(v, Bn)))) < 1e-9, "octet action leaves span"
            cols.append(v)
        return np.array(cols).T

    A_g3 = [rep_on_matspace(A, so3_basis) for A in Acol]     # geometric-3
    A_c5 = [rep_on_matspace(A, sym0_basis) for A in Acol]    # coset-5

    # ---- (3) spin content: Casimir ratios + independent ad(e12) weight spectra ----
    def casimir_mean(reps):
        C = sum(A @ A for A in reps)
        return float(np.mean(np.linalg.eigvalsh((C + C.T) / 2)))
    cas_col = casimir_mean(Acol)
    ratios = {"L": casimir_mean([A[:3, :3] for A in A2sp]) / cas_col,
              "Q": casimir_mean([A[3:, 3:] for A in A2sp]) / cas_col,
              "geometric-3": casimir_mean(A_g3) / cas_col,
              "coset-5": casimir_mean(A_c5) / cas_col}
    assert abs(ratios["L"] - 1) < 1e-9 and abs(ratios["Q"] - 1) < 1e-9, ratios
    assert abs(ratios["geometric-3"] - 1) < 1e-9 and abs(ratios["coset-5"] - 3) < 1e-9, ratios
    def weights(A):
        return sorted(np.round(np.linalg.eigvals(A).imag, 9).tolist())
    w_g2 = weights(ad_matrix(e(1, 2), G2))
    w_c5 = weights(rep_on_matspace(ad_matrix(e(1, 2), COL), sym0_basis))
    assert w_g2 == [-1.0, -1.0, 0.0, 0.0, 1.0, 1.0], w_g2
    assert w_c5 == [-2.0, -1.0, 0.0, 1.0, 2.0], w_c5

    # ---- (4) invariant-form counts (exact nullity of the intertwiner conditions) ----
    def nullity(M):
        s = np.linalg.svd(M, compute_uv=False)
        thr = 1e-9 * (s[0] if len(s) else 1.0)
        return int(np.sum(s < thr)) + max(0, M.shape[1] - len(s))
    def count_sym_inv(reps):
        n = reps[0].shape[0]
        cols = []
        for p in range(n):
            for q in range(p, n):
                Bm = np.zeros((n, n)); Bm[p, q] = 1.0; Bm[q, p] = 1.0
                cols.append(np.concatenate([(A.T @ Bm + Bm @ A).flatten() for A in reps]))
        return nullity(np.array(cols).T)
    def count_cross_inv(repsV, repsW):
        nV, nW = repsV[0].shape[0], repsW[0].shape[0]
        cols = []
        for p in range(nV):
            for q in range(nW):
                C = np.zeros((nV, nW)); C[p, q] = 1.0
                cols.append(np.concatenate([(AV.T @ C + C @ AW).flatten()
                                            for AV, AW in zip(repsV, repsW)]))
        return nullity(np.array(cols).T)

    counts = {
        "Spin(4) grade-2": count_sym_inv(A2), "Spin(4) grade-3": count_sym_inv(A3),
        "Spin(4) cross": count_cross_inv(A2, A3),
        "so(3) grade-2": count_sym_inv(A2sp),
        "so(3) L-Q cross": count_cross_inv([A[:3, :3] for A in A2sp], [A[3:, 3:] for A in A2sp]),
        "so(3) coset-5": count_sym_inv(A_c5),
        "so(3) cross(grade-2, coset-5)": count_cross_inv(A2sp, A_c5),
        "so(3) cross(grade-2, geometric-3)": count_cross_inv(A2sp, A_g3),
    }
    assert counts["Spin(4) grade-2"] == 2 and counts["Spin(4) grade-3"] == 1 and \
           counts["Spin(4) cross"] == 0, counts
    assert counts["so(3) grade-2"] == 3 and counts["so(3) L-Q cross"] == 1, counts
    assert counts["so(3) coset-5"] == 1, counts
    assert counts["so(3) cross(grade-2, coset-5)"] == 0, "THE NEGATIVE must be 0: %s" % counts
    assert counts["so(3) cross(grade-2, geometric-3)"] == 2, counts
    assert A2sp[0].shape[0] == 6 and A_c5[0].shape[0] == 5, "blocks must be 6- vs 5-dimensional"

    # ---- Z3-only scenario: cross count must be exactly 10 (two independent methods) ----
    th3 = 2 * math.pi / 3
    Bax = e(2, 3) - e(1, 3) + e(1, 2)
    Bax = (1.0 / math.sqrt(gr0(Bax * Bax.reverse()))) * Bax
    Rz3 = math.cos(th3 / 2) * SCALAR - math.sin(th3 / 2) * Bax
    img = Rz3 * e(1) * Rz3.reverse()
    assert abs(abs(gr0(img * e(2).reverse())) - 1.0) < 1e-9, "the Z3 rotor must cycle e1 -> e2"
    def conj_matrix(Rr, basis):
        return np.array([coeff_in(Rr * b * Rr.reverse(), basis) for b in basis]).T
    D2z = conj_matrix(Rz3, G2)
    Ucol = conj_matrix(Rz3, COL)
    Bn5 = [M / np.linalg.norm(M) for M in sym0_basis]
    D5z = np.array([[np.sum((Ucol @ M @ Ucol.T) * N) for M in Bn5] for N in Bn5])
    z3_cross = nullity(np.eye(30) - np.kron(D5z.T, D2z.T))
    assert z3_cross == 10, "Z3-only cross count must be exactly 10; got %d" % z3_cross
    c2 = Counter([int(round(m)) % 3 for m in w_g2]); c5 = Counter([int(round(m)) % 3 for m in w_c5])
    z3_from_weights = sum(c2[q] * c5[(-q) % 3] for q in set(c2))
    assert z3_from_weights == 10, "independent weights-mod-3 Z3 count must be 10; got %d" % z3_from_weights

    # ---- the R-151 route, both ways ----
    max_spin_g2 = max(np.max(np.linalg.eigvalsh(sum(A @ A for A in [A[:3, :3] for A in A2sp]))),
                      np.max(np.linalg.eigvalsh(sum(A @ A for A in [A[3:, 3:] for A in A2sp])))) / cas_col
    assert abs(max_spin_g2 - 1) < 1e-9, "R-151 value slots must top out at spatial spin 1"
    ASD_g = [ad_matrix(b, G2) for b in SDb]
    AASD_g = [ad_matrix(b, G2) for b in ASDb]
    reps_36 = [np.kron(A, np.eye(6)) for A in A2] + \
              [np.kron(np.eye(6), A) for A in ASD_g + AASD_g]
    n_F = count_sym_inv(reps_36)
    assert n_F == 4, "the EM F-quadratic slot must reproduce R-151's [Om,Om] count 4; got %d" % n_F

    # ---- banked sanity re-runs (read-only) ----
    gluon_octet_symmetric_space_split()
    theta_rel_z3_isotropy_dichotomy()

    return {
        "tier": ("DERIVED-A (the channel classification: the SIGNED identity, the identical "
                 "grade-3 vanishing with its grade-counting proof, the spin content, and every "
                 "invariant-form count) + LOCATED-GAP (the alpha_s fold-in reduction — "
                 "CONDITIONAL on the banked gluon-FRAMING channel assignment 'colour force = "
                 "coset-5' AND on the couplings-as-Im-chi-moments FRAMING)"),
        "signed_identity": "<B I4 B>_0 = |B_ASD|^2 - |B_SD|^2 = 2<B_L I4 B_Q>_0  (exact, signed)",
        "colour_sector_has_no_alpha_form": ("<X I4 X>_0 == 0 identically on grade-3 — grade "
                                            "counting: I4*X is grade 1, and grade-3 x grade-1 "
                                            "lands in grades 2 and 4 only, so no grade-0 exists"),
        "spin_content": {"L": "spin 1", "Q": "spin 1",
                         "grade-2": "multiplicity-2 spin-1 block (dim 6)",
                         "geometric-3": "spin 1", "coset-5": "spin 2 (dim 5)",
                         "casimir_ratios": {k: round(v, 6) for k, v in ratios.items()},
                         "ad(e12) weights grade-2": w_g2, "ad(e12) weights coset-5": w_c5},
        "invariant_form_counts": counts,
        "block_dimensions": {"grade-2": 6, "coset-5": 5,
                             "consequence": ("DIMENSIONALLY INEQUIVALENT — no invertible "
                                             "intertwiner can exist under ANY subgroup chain; "
                                             "the zero cross counts are the sharper statement")},
        "scenario_qualifiers": {
            "Spin(4) / spatial SO(3)": "cross-invariant count 0 — independent kernels break no symmetry",
            "one scalar K_5": "this is the SO(3)-SCENARIO count, not scenario-free",
            "Z3-only (open N10 binary)": ("cross-pairings ALLOWED, count exactly %d (two independent "
                                          "methods) — ALLOWED-BUT-UNFORCED: less symmetry gives MORE "
                                          "kernel freedom, never forced equality" % z3_cross),
            "N10 Z3-BROKEN NESS": "pushes BELOW the Z3-only scenario — a fortiori unforced",
        },
        "r151_route": {"EM": "fits — F-quadratic slot reproduces the [Om,Om] count 4",
                       "colour": "does NOT fit — coset-5 needs a spin-2 value slot; R-151's "
                                 "value slots top out at spatial spin 1"},
        "named_premise": ("kernel SPIN-CHANNEL UNIVERSALITY: Im chi_5 proportional to Im chi_1 "
                          "UP TO FREQUENCY-INDEPENDENT WEIGHTS — the same universality axis as "
                          "colour_arich_kernel_dependent Correction 2 / the map's 'couplings via "
                          "SOC universality'; the spin-2 block IS Theta_rel's own channel"),
        "open_cross_block_weight": ("the spin-1 <-> spin-2 normalization ratio is OPEN — there is "
                                    "no derived analogue of the 8/3 charge/Casimir ratio that fixes "
                                    "sin^2 theta_W = 3/8. This missing 8/3-analogue sits directly "
                                    "beside the one named kernel property and must be quoted with it."),
        "scope_fence": ("TWO-POINT / MAGNITUDE-SOURCE ONLY. NOT a dynamical-decoupling claim and "
                        "NOT about the RUNNING / AF face: at cubic order the banked [3,5] / [5,5] "
                        "brackets couple the sectors (non-abelian running is cubic physics); the "
                        "full-su(3) running correction stands verbatim. The EW trio's one-dial "
                        "reduction (R-035b) is untouched."),
        "would_change_if": ("(a) SOC/criticality universality of the NESS response is established "
                            "— supplies the named premise; (b) a substrate symmetry intertwining "
                            "grade-2 with coset-5 is exhibited (none exists — every banked symmetry "
                            "is grade-preserving; would need genuinely new structure, e.g. a "
                            "triality-like automorphism); (c) an ALGEBRAIC sibling bridge for g_s "
                            "is derived (which would also supply the missing cross-block weight); "
                            "(d) the gluon-FRAMING channel assignment is revised"),
    }


